from sqlalchemy.orm import Session

from app.models import Chunk
from app.services.embedding_service import generate_embeddings

def save_chunks(db: Session, document_id, chunks):
    db_chunks = []

    for chunk in chunks:
        db_chunk = Chunk(
            document_id=document_id,
            chunk_index=chunk["chunk_index"],
            page_number=chunk["page_number"],
            content=chunk["text"]
        )

        db_chunks.append(db_chunk)

    db.add_all(db_chunks)
    db.commit()

    return len(db_chunks)

# Takes the chunks generated by our chunking service and saves them in the document_chunks table, linked to their original PDF.

def generate_and_save_embeddings(db: Session, document_id):
    chunks = (
        db.query(Chunk)
        .filter(Chunk.document_id == document_id)
        .order_by(Chunk.chunk_index)
        .all()
    )

    if not chunks:
        return 0

    texts = [chunk.content for chunk in chunks]
    embeddings = generate_embeddings(texts)

    for chunk, embedding in zip(chunks, embeddings):
        chunk.embedding = embedding

    db.commit()

    return len(chunks)